{"type":"user","message":{"role":"user","content":[{"tool_use_id":"chatcmpl-tool-86a16c3890093979","type":"tool_result","content":"1\t#!/usr/bin/env python3\n2\t\"\"\"Deterministic pre-submit validation for one strategy's epic decomposition.\n3\t\n4\tChecks the mechanically decidable contract rules that the downstream judges\n5\tand submit.py enforce — the ones an LLM step can silently get wrong while the\n6\tdecomposition still looks good:\n7\t\n8\t  1. Epic body sections: every epic file must carry headings covering\n9\t     Description, Scope, Acceptance Criteria, and HLR Traceability (matched on\n10\t     heading text at any level, exactly like the artifact contract).\n11\t  2. Component vocabulary: every epic's `component` frontmatter value must be\n12\t     verbatim in .context/rhai-components.txt (submit.py silently strips\n13\t     unknown names, leaving the Jira epic component-less).\n14\t  3. Rule 11 (docs-last): every docs-authoring epic must be blocked, directly\n15\t     or transitively, by every main-plan Implementation epic that is not\n16\t     itself docs-authoring.\n17\t  4. Priority inheritance: an epic that directly or transitively enables a P0\n18\t     epic must itself be P0 (docs-authoring epics are exempt; branch epics\n19\t     are conditional alternatives and out of scope).\n20\t  5. Implementation-type parallelism (Rules 7/8/10): no `dependencies` edge,\n21\t     in either direction, between a license-validation and a repo-onboarding\n22\t     epic (Rule 7), a license-validation and a konflux-onboarding epic\n23\t     (Rule 8), or a konflux-onboarding and a general implementation epic\n24\t     (Rule 10) — these pairs must run in parallel; any real coupling is an\n25\t     acceptance-criterion gate, never a DAG edge. Edges into a docs-authoring\n26\t     epic are exempt (Rule 11 requires them).\n27\t  6. Shared-surface enforcement deliverables: a general Implementation epic\n28\t     whose deliverable is an enforcement tool (lint rule, CI check,\n29\t     static-analysis check, validation harness) over surfaces that other\n30\t     same-component Implementation epics implement is a work-type extraction —\n31\t     the deliverable belongs in each consuming epic's Scope/ACs, divided per\n32\t     surface, not in a standalone epic.\n33\t\n34\tExit 0 with \"OK\" when clean; exit 1 with one line per violation otherwise.\n35\t\n36\tUsage:\n37\t    python3 skills/epic-decompose/scripts/validate_decomposition.py <STRAT_ID> \\\n38\t        [--artifacts-dir artifacts] [--components .context/rhai-components.txt]\n39\t    python3 skills/epic-decompose/scripts/validate_decomposition.py --self-check\n40\t\"\"\"\n41\t\n42\timport argparse\n43\timport os\n44\timport re\n45\timport sys\n46\t\n47\timport yaml\n48\t\n49\tSECTIONS = [(\"Description\", (\"description\",)),\n50\t            (\"Scope\", (\"scope\",)),\n51\t            (\"Acceptance Criteria\", (\"acceptance criteria\",)),\n52\t            (\"HLR Traceability\", (\"hlr traceability\", \"traceability\"))]\n53\t\n54\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n55\t\n56\tIT_ENUM = (\"docs-authoring\", \"konflux-onboarding\", \"license-validation\",\n57\t           \"repo-onboarding\")\n58\t\n59\t# Pairs of implementation kinds that must run in parallel (no DAG edge either\n60\t# way) — parity with the implementation_type_rules judge.\n61\tPARALLEL_PAIRS = {\n62\t    frozenset((\"license-validation\", \"repo-onboarding\")): \"Rule 7\",\n63\t    frozenset((\"license-validation\", \"konflux-onboarding\")): \"Rule 8\",\n64\t    frozenset((\"konflux-onboarding\", \"general\")): \"Rule 10\",\n65\t}\n66\t\n67\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n68\t\n69\t# An epic whose title names an enforcement tool over code surfaces — the\n70\t# deliverable shape that must be divided per surface into the consuming epics,\n71\t# never extracted into a standalone work-type epic.\n72\tENFORCEMENT_TITLE_RE = re.compile(\n73\t    r'\\b(lint|static[ -]analysis|CI (check|pipeline|gate|lint)|'\n74\t    r'validation harness|code check)\\b', re.I)\n75\t\n76\t\n77\tdef read_frontmatter(path):\n78\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n79\t    with open(path, encoding=\"utf-8\") as f:\n80\t        content = f.read()\n81\t    m = FRONTMATTER_RE.match(content)\n82\t    if not m:\n83\t        return {}, content\n84\t    try:\n85\t        data = yaml.safe_load(m.group(1))\n86\t    except yaml.YAMLError:\n87\t        return {}, content\n88\t    if not isinstance(data, dict):\n89\t        return {}, content\n90\t    return data, content[m.end():]\n91\t\n92\t\n93\tdef body_headings(body):\n94\t    heads = []\n95\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n96\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n97\t    return heads\n98\t\n99\t\n100\tdef load_epics(artifacts_dir, strat_id):\n101\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n102\t\n103\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n104\t    \"\"\"\n105\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n106\t    if not os.path.isdir(task_dir):\n107\t        return {}\n108\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n109\t    epics = {}\n110\t    for name in sorted(os.listdir(task_dir)):\n111\t        m = pat.match(name)\n112\t        if not m:\n113\t            continue\n114\t        path = os.path.join(task_dir, name)\n115\t        fm, body = read_frontmatter(path)\n116\t        epics[name[:-3]] = (path, fm, body)\n117\t    return epics\n118\t\n119\t\n120\tdef dependency_closure(start_key, deps):\n121\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n122\t    seen, stack = set(), list(deps.get(start_key, []))\n123\t    while stack:\n124\t        n = stack.pop()\n125\t        if n in seen or n not in deps:\n126\t            continue\n127\t        seen.add(n)\n128\t        stack.extend(deps[n])\n129\t    return seen\n130\t\n131\t\n132\tdef check(strat_id, artifacts_dir, components_path):\n133\t    \"\"\"Run all checks; return a list of violation strings.\"\"\"\n134\t    probs = []\n135\t    epics = load_epics(artifacts_dir, strat_id)\n136\t    if not epics:\n137\t        return [\"no epic files found for %s under %s/epic-tasks/\"\n138\t                % (strat_id, artifacts_dir)]\n139\t\n140\t    valid_components = set()\n141\t    if os.path.isfile(components_path):\n142\t        with open(components_path, encoding=\"utf-8\") as f:\n143\t            valid_components = {ln.strip() for ln in f if ln.strip()}\n144\t    if not valid_components:\n145\t        probs.append(\"cannot read canonical component list %s — verify the \"\n146\t                     \"path before trusting component names\" % components_path)\n147\t\n148\t    deps, is_branch, is_docs, is_impl, itype, prio = {}, {}, {}, {}, {}, {}\n149\t    component_of = {}\n150\t    fm_titles = {}\n151\t    for key, (path, fm, body) in epics.items():\n152\t        name = key + \".md\"\n153\t        # 1. body sections (contract parity with the artifact judge)\n154\t        heads = body_headings(body)\n155\t        for want, aliases in SECTIONS:\n156\t            if not any(a in h for h in heads for a in aliases):\n157\t                probs.append(\"%s: body missing '%s' section (required \"\n158\t                             \"sections: Description, Scope, Acceptance \"\n159\t                             \"Criteria, HLR Traceability)\" % (name, want))\n160\t        # 2. component vocabulary\n161\t        comp = fm.get(\"component\")\n162\t        if valid_components and isinstance(comp, str) and comp.strip() \\\n163\t                and comp.strip() not in valid_components:\n164\t            probs.append(\"%s: component '%s' is not in %s — pick the closest \"\n165\t                         \"canonical name (submit.py strips unknown names)\"\n166\t                         % (name, comp.strip(), components_path))\n167\t        # collect graph facts\n168\t        dl = fm.get(\"dependencies\")\n169\t        deps[key] = [x for x in dl if isinstance(x, str)] \\\n170\t            if isinstance(dl, list) else []\n171\t        is_branch[key] = \"BRANCH-\" in key\n172\t        is_docs[key] = fm.get(\"implementation_type\") == \"docs-authoring\"\n173\t        is_impl[key] = fm.get(\"type\") == \"Implementation\"\n174\t        component_of[key] = comp_val if isinstance(comp_val := fm.get(\"component\"),\n175\t                                           str) else \"\"\n176\t        fm_titles[key] = fm.get(\"title\") if isinstance(fm.get(\"title\"),\n177\t                                                       str) else \"\"\n178\t        it = fm.get(\"implementation_type\")\n179\t        itype[key] = it if it in IT_ENUM else None\n180\t        prio[key] = fm.get(\"priority\")\n181\t\n182\t    def kind(key):\n183\t        \"\"\"Implementation kind of an epic — parity with the judge: an epic\n184\t        that is not type Implementation is never a parallel-rule party; an\n185\t        Implementation epic's kind is its implementation_type when that is a\n186\t        known label, else 'general'.\"\"\"\n187\t        if not is_impl[key]:\n188\t            return \"non-implementation\"\n189\t        return itype[key] or \"general\"\n190\t\n191\t    # 3. Rule 11 — docs-authoring blocked by every main-plan Implementation\n192\t    universe = [k for k in epics\n193\t                if is_impl[k] and not is_docs[k] and not is_branch[k]]\n194\t    for k in sorted(epics):\n195\t        if not is_docs[k]:\n196\t            continue\n197\t        cl = dependency_closure(k, deps)\n198\t        missing = sorted(e for e in universe if e != k and e not in cl)\n199\t        if missing:\n200\t            probs.append(\"Rule 11: docs-authoring %s is not blocked by every \"\n201\t                         \"Implementation epic — add %s to its dependency chain\"\n202\t                         % (k, \", \".join(missing)))\n203\t\n204\t    # 4. Priority inheritance — enablers of P0 work must be P0\n205\t    for k in sorted(epics):\n206\t        if is_branch[k] or is_docs[k]:\n207\t            continue\n208\t        if prio.get(k) != \"P0\":\n209\t            continue\n210\t        # every main-plan, non-docs epic in k's closure enables P0 work\n211\t        cl = dependency_closure(k, deps)\n212\t        for t in sorted(cl):\n213\t            if is_branch[t] or is_docs[t]:\n214\t                continue\n215\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n216\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n217\t                             \"but is %s — raise it to P0 or restructure\"\n218\t                             % (t, prio.get(t), k, prio.get(t)))\n219\t\n220\t    # 5. Rules 7/8/10 — implementation-type parallelism: the mandated-parallel\n221\t    #    pairs carry no dependencies edge in either direction (direct edges\n222\t    #    only; edges into a docs-authoring epic are exempt — Rule 11 requires\n223\t    #    them; dependencies naming epics with no file cannot be judged).\n224\t    for k in sorted(epics):\n225\t        if kind(k) == \"docs-authoring\":\n226\t            continue\n227\t        for t in deps[k]:\n228\t            if t not in epics:\n229\t                continue\n230\t            pair = frozenset((kind(t), kind(k)))\n231\t            rule = PARALLEL_PAIRS.get(pair)\n232\t            if rule:\n233\t                probs.append(\"%s: %s (%s) blocks %s (%s) — these must run in \"\n234\t                             \"parallel; remove the dependencies edge and \"\n235\t                             \"express any coupling as an AC gate on the \"\n236\t                             \"dependent epic\"\n237\t                             % (rule, t, kind(t), k, kind(k)))\n238\t\n239\t    # 6. Shared-surface enforcement deliverables — an enforcement-tool epic\n240\t    #    (lint rule / CI check / static-analysis check / validation harness,\n241\t    #    detected by title) that shares its component with at least one other\n242\t    #    non-docs Implementation epic is a work-type extraction: fold the\n243\t    #    deliverable into each consuming epic's Scope/ACs per surface and\n244\t    #    delete the standalone epic. Not fired when the enforcement tool is\n245\t    #    the component's only implementation work (a legitimate standalone).\n246\t    for k in sorted(epics):\n247\t        if not is_impl[k] or is_docs[k] or is_branch[k]:\n248\t            continue\n249\t        title = fm_titles.get(k, \"\")\n250\t        if not ENFORCEMENT_TITLE_RE.search(title):\n251\t            continue\n252\t        siblings = [t for t in sorted(epics)\n253\t                    if t != k and is_impl[t] and not is_docs[t]\n254\t                    and not is_branch[t] and component_of.get(t) == component_of.get(k)]\n255\t        if siblings:\n256\t            probs.append(\"%s: standalone enforcement deliverable (%r) over \"\n257\t                         \"surfaces implemented by same-component epic(s) %s — \"\n258\t                         \"divide the enforcement deliverable per surface into \"\n259\t                         \"each consuming epic's Scope and Acceptance \"\n260\t                         \"Criteria, delete this epic, and update the summary \"\n261\t                         \"(Epic List, DAG, traceability); do not keep a \"\n262\t                         \"standalone work-type epic\"\n263\t                         % (k, title, \", \".join(siblings)))\n264\t    return probs\n265\t\n266\t\n267\t# ─── self-check ───────────────────────────────────────────────────────────────\n268\t\n269\tdef _self_check():\n270\t    \"\"\"Verify each check fires on a minimal bad fixture and passes a good one.\"\"\"\n271\t    import shutil\n272\t    import tempfile\n273\t\n274\t    tmp = tempfile.mkdtemp(prefix=\"validate-decomp-selfcheck-\")\n275\t    try:\n276\t        art = os.path.join(tmp, \"artifacts\", \"epic-tasks\")\n277\t        os.makedirs(art)\n278\t        comp = os.path.join(tmp, \"components.txt\")\n279\t        with open(comp, \"w\") as f:\n280\t            f.write(\"Dashboard\\nServing Runtimes\\n\")\n281\t\n282\t        def write(name, fm, body):\n283\t            with open(os.path.join(art, name), \"w\") as f:\n284\t                f.write(\"---\\n%s\\n---\\n%s\" % (fm, body))\n285\t\n286\t        good_body = (\"# T\\n## Description\\nd\\n## Scope\\ns\\n\"\n287\t                     \"## Acceptance Criteria\\na\\n## HLR Traceability\\nh\\n\")\n288\t        write(\"RHAISTRAT-9001-E001.md\",\n289\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n290\t              \"dependencies: []\\n\", good_body)\n291\t        write(\"RHAISTRAT-9001-E002.md\",\n292\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n293\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n294\t              \"dependencies: [RHAISTRAT-9001-E001, RHAISTRAT-9001-E003]\\n\",\n295\t              good_body)\n296\t        # a konflux-onboarding epic parallel to the general epic (no edge\n297\t        # either way) is the Rule 10-compliant shape — must not be flagged\n298\t        write(\"RHAISTRAT-9001-E003.md\",\n299\t              \"component: Dashboard\\ntype: Implementation\\n\"\n300\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n301\t              \"dependencies: []\\n\", good_body)\n302\t        assert check(\"RHAISTRAT-9001\", os.path.join(tmp, \"artifacts\"),\n303\t                     comp) == [], \"good fixture must pass cleanly\"\n304\t\n305\t        # bad fixture: missing Scope, bad component, Rule 11 gap, P0->P1 edge,\n306\t        # Rule 10 konflux-onboarding -> general edge\n307\t        write(\"RHAISTRAT-9002-E001.md\",\n308\t              \"component: Model Serving Stack\\ntype: Implementation\\n\"\n309\t              \"priority: P0\\ndependencies: [RHAISTRAT-9002-E002]\\n\",\n310\t              \"# T\\n## Description\\nd\\n## Acceptance Criteria\\na\\n\"\n311\t              \"## HLR Traceability\\nh\\n\")\n312\t        write(\"RHAISTRAT-9002-E002.md\",\n313\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n314\t              \"dependencies: []\\n\", good_body)\n315\t        write(\"RHAISTRAT-9002-E003.md\",\n316\t              \"component: Dashboard\\ntype: Implementation\\n\"\n317\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n318\t              \"dependencies: [RHAISTRAT-9002-E001]\\n\", good_body)\n319\t        # E004 is a main-plan Implementation the docs epic never depends on\n320\t        write(\"RHAISTRAT-9002-E004.md\",\n321\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n322\t              \"dependencies: [RHAISTRAT-9002-E005]\\n\", good_body)\n323\t        write(\"RHAISTRAT-9002-E005.md\",\n324\t              \"component: Dashboard\\ntype: Implementation\\n\"\n325\t              \"implementation_type: konflux-onboarding\\npriority: P1\\n\"\n326\t              \"dependencies: []\\n\", good_body)\n327\t        probs = check(\"RHAISTRAT-9002\", os.path.join(tmp, \"artifacts\"), comp)\n328\t        joined = \"\\n\".join(probs)\n329\t        assert \"missing 'Scope'\" in joined, probs\n330\t        assert \"Model Serving Stack\" in joined, probs\n331\t        assert \"Rule 11\" in joined and \"E004\" in joined, probs\n332\t        assert \"priority inheritance\" in joined and \"E002\" in joined, probs\n333\t        r10 = [p for p in probs if p.startswith(\"Rule 10:\")]\n334\t        assert len(r10) == 1 and \"E005\" in r10[0] and \"E004\" in r10[0], probs\n335\t\n336\t        # check 6 positive: standalone enforcement epic over same-component\n337\t        # implementation work must be flagged\n338\t        write(\"RHAISTRAT-9003-E001.md\",\n339\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n340\t              \"title: Convert manager binary log calls to structured fields\\n\"\n341\t              \"dependencies: []\\n\", good_body)\n342\t        write(\"RHAISTRAT-9003-E002.md\",\n343\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n344\t              \"title: CI lint rule enforcing structured log fields\\n\"\n345\t              \"dependencies: []\\n\", good_body)\n346\t        probs = check(\"RHAISTRAT-9003\", os.path.join(tmp, \"artifacts\"), comp)\n347\t        c6 = [p for p in probs if p.startswith(\"RHAISTRAT-9003-E002:\")]\n348\t\n349\t        # check 6 negative: enforcement tool as the component's ONLY\n350\t        # implementation epic is legitimate — must not be flagged\n351\t        write(\"RHAISTRAT-9004-E001.md\",\n352\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n353\t              \"title: CI lint rule for release notes format\\n\"\n354\t              \"dependencies: []\\n\", good_body)\n355\t        write(\"RHAISTRAT-9004-E002.md\",\n356\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n357\t              \"priority: P0\\n\"\n358\t              \"title: Serving runtime config migration\\n\"\n359\t              \"dependencies: []\\n\", good_body)\n360\t        assert check(\"RHAISTRAT-9004\", os.path.join(tmp, \"artifacts\"),\n361\t                     comp) == [], \"lone enforcement epic must pass cleanly\"\n362\t        assert len(c6) == 1 and \"per surface\" in c6[0], probs\n363\t        print(\"self-check OK: 6 checks fire on bad fixtures, clean on good\")\n364\t        return 0\n365\t    finally:\n366\t        shutil.rmtree(tmp, ignore_errors=True)\n367\t\n368\t\n369\tdef main(argv=None):\n370\t    ap = argparse.ArgumentParser(description=__doc__)\n371\t    ap.add_argument(\"strat_id\", nargs=\"?\", help=\"e.g. RHAISTRAT-9013\")\n372\t    ap.add_argument(\"--artifacts-dir\", default=\"artifacts\")\n373\t    ap.add_argument(\"--components\",\n374\t                    default=\".context/rhai-components.txt\")\n375\t    ap.add_argument(\"--self-check\", action=\"store_true\")\n376\t    args = ap.parse_args(argv)\n377\t\n378\t    if args.self_check:\n379\t        return _self_check()\n380\t    if not args.strat_id:\n381\t        ap.error(\"strat_id is required (unless --self-check)\")\n382\t\n383\t    probs = check(args.strat_id, args.artifacts_dir, args.components)\n384\t    if probs:\n385\t        for p in probs:\n386\t            print(\"VIOLATION: %s\" % p)\n387\t        print(\"%d violation(s) — fix these before marking the decomposition \"\n388\t              \"complete\" % len(probs))\n389\t        return 1\n390\t    print(\"OK: contract checks passed for %s\" % args.strat_id)\n391\t    return 0\n392\t\n393\t\n394\tif __name__ == \"__main__\":\n395\t    sys.exit(main())\n396\t"}]},"parent_tool_use_id":"chatcmpl-tool-96ffdecdd766e6e1","agent_id":"add362e9569eaf60d","session_id":"6d4629bb-6ebf-4841-9add-2a02bfaa2227","uuid":"838e9594-5083-46cc-a6eb-d3d8698cf1e9","timestamp":"2026-10-26T15:07:18.362Z","tool_result_meta":[{"id":"chatcmpl-tool-86a16c3890093979","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"claude","task_description":"Decompose RHAISTRAT-9015 into epics"}
